 "draft", "id": "51dd26f2-b17c-5bf3-bce8-0ec7ef4c11a0", "subject_id": "1feb2123-a637-58ac-96c1-89cee92662ca", "source_id": "91bb2f60-b25f-544e-aaf7-44156fdcf021"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》详记昭宗欲召敬翔、朱全忠令敬翔私退。", "citation": "《旧唐书》卷二十上，段落 jiu-tangshu-b729c4ac3d3b-p003315；EPUB电子本，纸本及异文待核", "note": "原文：全忠既不欲來，即令敬翔來，朕與之言。；核对说明：此书另给昭宗宴席谈话细节；未将谈话外推为设伏。", "status": "draft", "id": "df235d0a-2a24-5062-b779-279c6519ce8a", "subject_id": "29b56645-b90d-50a2-b255-3dc26263fee3", "source_id": "91bb2f60-b25f-544e-aaf7-44156fdcf021"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧唐书》作五月己巳朱全忠辞赴大梁，与《通鉴》辛未东还异日。", "citation": "《旧唐书》卷二十上，段落 jiu-tangshu-b729c4ac3d3b-p003315；EPUB电子本，纸本及异文待核", "note": "原文：己巳，全忠辭赴大梁；核对说明：日分不同；两书各自保留，不强合出发日。", "status": "draft", "id": "69051cf1-8eb0-5d9e-b602-c502c0e02ab0", "subject_id": "a6d7d16a-1bfe-5665-9da1-3b7fbfc686de", "source_id": "91bb2f60-b25f-544e-aaf7-44156fdcf021"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》六月条记朱全忠遣朱友裕屯百仁村。", "citation": "《旧唐书》卷二十上，段落 jiu-tangshu-b729c4ac3d3b-p003316；EPUB电子本，纸本及异文待核", "note": "原文：全忠遣朱友裕屯軍於百仁村；核对说明：补充屯军地点；不能据此推定与《通鉴》“行营都统”同日任命。", "status": "draft", "id": "aa0cdc6a-ee5d-51a2-be42-c6581ed228d9", "subject_id": "e74e285d-91a3-5e9a-85fc-72c5e6e4def4", "source_id": "ad13ef94-f3e5-536b-8e71-4b9ee217a24e"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧唐书》记七月癸亥朔朱全忠率师讨邠凤，甲子自汴至洛阳。", "citation": "《旧唐书》卷二十上，段落 jiu-tangshu-b729c4ac3d3b-p003317；EPUB电子本，纸本及异文待核", "note": "原文：七月癸亥朔，全忠率師討邠、鳳。甲子，自汴至洛陽；核对说明：印证七月经洛阳；六月癸丑自大梁西讨仍据主书。", "status": "draft", "id": "8c892f33-ffb6-5977-a201-177bcfa246ad", "subject_id": "d056c058-4d22-5d02-b4a2-9c695a0c4e73", "source_id": "ee5b4ba4-4a59-5aad-bd78-a3bf884fd8ec"}]'::jsonb)
